//! Disposable benchmark of existing String key operations and Map lookup.
#[path = "../tests/support/oop.rs"]
mod oop;
use birnam_abi::{size, Oop};
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let h = oop::bootstrap();
    let q = h.scope();
    let yes = h.named(b"true").unwrap();
    for length in [16, 4096, 1048576] {
        let bytes = vec![b'x'; length];
        let left = q.string(&bytes).unwrap();
        let right = q.string(&bytes).unwrap();
        let expected_hash = bytes.iter().fold(2_166_136_261u32,
            |hash, &byte| (hash ^ u32::from(byte)).wrapping_mul(16_777_619));
        let map = q.call(h.named(b"Map").unwrap(), b"at:put:", &[left, yes]).unwrap();
        let calls = match length { 16 => 100000, 4096 => 4096, _ => 128 };
        let cases: &[(&str, Oop, &[u8], &[Oop], Oop)] = &[
            ("hash", left, b"collectionHash", &[], size(expected_hash as usize).unwrap()),
            ("equal", left, b"collectionEquals:", &[right], yes),
            ("lookup", map, b"at:", &[right], yes),
        ];
        for &(name, receiver, selector, args, expected) in cases {
            let selector = q.keep(h.intern(selector).unwrap()).unwrap();
            for _ in 0..10 { assert_eq!(unsafe { h.id.send(receiver, selector, args).unwrap() }, expected); }
            for _ in 0..5 {
                let start = unsafe { clock_gettime_nsec_np(16) };
                for _ in 0..calls { assert_eq!(unsafe { h.id.send(receiver, selector, args).unwrap() }, expected); }
                println!("{length} {name} {calls} {}", unsafe { clock_gettime_nsec_np(16) } - start);
            }
        }
    }
}
